from itertools import combinations
import random
from collections import deque

n = 24

def girth(adj):
    g = float('inf')
    for src in range(n):
        dist={src:0}; parent={src:-1}; q=deque([src])
        while q:
            u=q.popleft()
            for v in adj[u]:
                if v not in dist:
                    dist[v]=dist[u]+1; parent[v]=u; q.append(v)
                elif parent[u]!=v:
                    c=dist[u]+dist[v]+1
                    if c<g: g=c
                    if g<=6: return g
    return g

# Randomized construction: start with Hamiltonian cycle, add random chords avoiding short cycles
def try_build(seed):
    random.seed(seed)
    adj = {i:set() for i in range(n)}
    for i in range(n):
        adj[i].add((i+1)%n); adj[(i+1)%n].add(i)
    # need each vertex to have degree 3 or 4. Currently all have degree 2.
    # Add chords. Each chord increases 2 degrees by 1.
    # To make 3-regular, add 12 chords (perfect matching on non-cycle edges).

    # For two vertices u,v (non-adjacent), adding edge u-v is OK if shortest path between them is >= 6.
    candidates = [(u,v) for u,v in combinations(range(n),2) if v not in adj[u]]
    random.shuffle(candidates)

    def bfs_dist(s,t,limit):
        if s==t: return 0
        dist={s:0}; q=deque([s])
        while q:
            u=q.popleft()
            if dist[u]>=limit: continue
            for v in adj[u]:
                if v not in dist:
                    dist[v]=dist[u]+1
                    if v==t: return dist[v]
                    q.append(v)
        return float('inf')

    deg_target = 3
    added = 0
    for u,v in candidates:
        if len(adj[u])>=deg_target or len(adj[v])>=deg_target: continue
        d = bfs_dist(u,v,6)
        if d >= 6:  # cycle length would be d+1 >=7
            adj[u].add(v); adj[v].add(u)
            added += 1
    # Check if all have degree 3
    degs = [len(adj[i]) for i in range(n)]
    return adj, degs

best = None
for s in range(2000):
    adj, degs = try_build(s)
    if min(degs)>=3 and max(degs)<=4:
        g = girth(adj)
        if g >= 7:
