from itertools import combinations

n = 24

def girth_adj(adj):
    g = float('inf')
    for src in range(n):
        dist={src:0}; parent={src:-1}; q=deque([src])
        while q:
            u=q.popleft()
            for v in adj[u]:
                if v not in dist:
                    dist[v]=dist[u]+1; parent[v]=u; q.append(v)
                elif parent[u]!=v:
                    c=dist[u]+dist[v]+1
                    if c<g: g=c
    return g

def bfs_dist(adj,s,t,limit):
    if s==t: return 0
    dist={s:0}; q=deque([s])
    while q:
        u=q.popleft()
        if dist[u]>=limit: continue
        for v in adj[u]:
            if v not in dist:
                dist[v]=dist[u]+1
                if v==t: return dist[v]
                q.append(v)
    return float('inf')

def try_build(seed):
    random.seed(seed)
    adj = {i:set() for i in range(n)}
    # Start with Hamiltonian cycle
    for i in range(n):
